import test from 'node:test';
import assert from 'node:assert/strict';
import { recordPayment, balanceDue } from '../src/payments.js';
import { createInvoice, invoiceTotals, issueInvoice } from '../src/invoices.js';

test('recordPayment adds a payment to an issued invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;

  const result = recordPayment(issuedInvoice, { amount: 5000, date: '2025-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.payments.length, 1);
  assert.equal(result.value.payments[0].amount, 5000);
  assert.equal(result.value.payments[0].date, '2025-10-08');
});

test('recordPayment sets status to partially_paid when balance remains', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const invoiceTotal = invoiceTotals(issuedInvoice).total;

  const result = recordPayment(issuedInvoice, { amount: invoiceTotal - 1000, date: '2025-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'partially_paid');
});

test('recordPayment sets status to paid when balance is zero', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const invoiceTotal = invoiceTotals(issuedInvoice).total;

  const result = recordPayment(issuedInvoice, { amount: invoiceTotal, date: '2025-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'paid');
});

test('recordPayment adds payments to partially_paid invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const invoiceTotal = invoiceTotals(issuedInvoice).total;

  const result1 = recordPayment(issuedInvoice, { amount: 5000, date: '2025-10-08' });
  assert.equal(result1.ok, true);
  assert.equal(result1.value.status, 'partially_paid');

  const result2 = recordPayment(result1.value, { amount: invoiceTotal - 5000, date: '2025-10-09' });
  assert.equal(result2.ok, true);
  assert.equal(result2.value.status, 'paid');
  assert.equal(result2.value.payments.length, 2);
});

test('recordPayment reports NOT_ISSUED for draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;

  const result = recordPayment(invoice, { amount: 5000, date: '2025-10-08' });
  assert.deepEqual(result, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment reports NOT_ISSUED for sent invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'sent',
    number: 'INV-2025-0001',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
  };

  const result = recordPayment(invoice, { amount: 5000, date: '2025-10-08' });
  assert.deepEqual(result, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment reports AMOUNT_INVALID for zero amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;

  const result = recordPayment(issuedInvoice, { amount: 0, date: '2025-10-08' });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment reports AMOUNT_INVALID for negative amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;

  const result = recordPayment(issuedInvoice, { amount: -5000, date: '2025-10-08' });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment reports AMOUNT_INVALID for non-integer amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;

  const result = recordPayment(issuedInvoice, { amount: 5000.5, date: '2025-10-08' });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment reports OVERPAYMENT when payment exceeds balance', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const invoiceTotal = invoiceTotals(issuedInvoice).total;

  const result = recordPayment(issuedInvoice, { amount: invoiceTotal + 1, date: '2025-10-08' });
  assert.deepEqual(result, { ok: false, error: 'OVERPAYMENT' });
});

test('recordPayment reports OVERPAYMENT on partially paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const invoiceTotal = invoiceTotals(issuedInvoice).total;

  const result1 = recordPayment(issuedInvoice, { amount: 5000, date: '2025-10-08' });
  const result2 = recordPayment(result1.value, { amount: invoiceTotal - 4999, date: '2025-10-09' });

  assert.deepEqual(result2, { ok: false, error: 'OVERPAYMENT' });
});

test('recordPayment does not mutate the input invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const originalStatus = issuedInvoice.status;

  recordPayment(issuedInvoice, { amount: 5000, date: '2025-10-08' });
  assert.equal(issuedInvoice.status, originalStatus);
  assert.equal(issuedInvoice.payments, undefined);
});

test('balanceDue returns invoice total when no payments', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const invoiceTotal = invoiceTotals(issuedInvoice).total;

  assert.equal(balanceDue(issuedInvoice), invoiceTotal);
});

test('balanceDue subtracts payments from total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const invoiceTotal = invoiceTotals(issuedInvoice).total;

  const result = recordPayment(issuedInvoice, { amount: 5000, date: '2025-10-08' });
  assert.equal(balanceDue(result.value), invoiceTotal - 5000);
});

test('balanceDue with multiple payments', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const invoiceTotal = invoiceTotals(issuedInvoice).total;

  const result1 = recordPayment(issuedInvoice, { amount: 3000, date: '2025-10-08' });
  const result2 = recordPayment(result1.value, { amount: 2000, date: '2025-10-09' });
  assert.equal(balanceDue(result2.value), invoiceTotal - 5000);
});

test('balanceDue returns zero when fully paid', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const invoiceTotal = invoiceTotals(issuedInvoice).total;

  const result = recordPayment(issuedInvoice, { amount: invoiceTotal, date: '2025-10-08' });
  assert.equal(balanceDue(result.value), 0);
});

test('recordPayment with complex invoice with discounts and VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 5 },
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 },
    ],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const invoiceTotal = invoiceTotals(issuedInvoice).total;

  const result = recordPayment(issuedInvoice, { amount: invoiceTotal, date: '2025-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'paid');
  assert.equal(balanceDue(result.value), 0);
});

test('recordPayment preserves other invoice properties', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;

  const result = recordPayment(issuedInvoice, { amount: 5000, date: '2025-10-08' });
  assert.equal(result.value.customerId, issuedInvoice.customerId);
  assert.equal(result.value.issueDate, issuedInvoice.issueDate);
  assert.equal(result.value.number, issuedInvoice.number);
  assert.equal(result.value.lines.length, issuedInvoice.lines.length);
});

test('balanceDue handles invoices with no payments property', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'issued',
    number: 'INV-2025-0001',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
  };

  const balance = balanceDue(invoice);
  assert.equal(balance, invoiceTotals(invoice).total);
});

test('recordPayment with small amounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const invoiceTotal = invoiceTotals(issuedInvoice).total;

  const result = recordPayment(issuedInvoice, { amount: invoiceTotal, date: '2025-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'paid');
});

test('recordPayment with large amounts', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const invoiceTotal = invoiceTotals(issuedInvoice).total;

  const result = recordPayment(issuedInvoice, { amount: invoiceTotal, date: '2025-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'paid');
});

test('recordPayment tracks multiple payment dates', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issuedResult = issueInvoice(invoice, []);
  const issuedInvoice = issuedResult.value;
  const invoiceTotal = invoiceTotals(issuedInvoice).total;

  const result1 = recordPayment(issuedInvoice, { amount: 3000, date: '2025-10-08' });
  const result2 = recordPayment(result1.value, { amount: 3000, date: '2025-10-10' });
  const result3 = recordPayment(result2.value, { amount: invoiceTotal - 6000, date: '2025-10-12' });

  assert.equal(result3.value.payments[0].date, '2025-10-08');
  assert.equal(result3.value.payments[1].date, '2025-10-10');
  assert.equal(result3.value.payments[2].date, '2025-10-12');
});

